    jeweller: 1,
    chromatic: 2,
    fusing: 3,
    transmutation: 4,
    chance: 5,
    alchemy: 6,
    augment: 7,
    alteration: 8,
    exalted: 9,
    chaos: 10,
    regal: 11,
    scouring: 12,
