  /**
   * UNIQUE_ITEM_CATALOG 将紧凑静态行恢复成界面和 Roll 判断使用的具名对象。
   * 静态数据采用行结构只是为了控制油猴脚本体积，功能代码保持完整可读。
   */
  const JEWEL_RADIUS_LABELS = {
    small: '小',
    medium: '中',
    large: '大',
    veryLarge: '超大',
    massive: '巨型',
  };
  const hydrateUniqueJewelRadius = (row) => {
    if (!Array.isArray(row)) return null;
    return {
      mode: Number(row[0]) === 2 ? 'variable' : Number(row[0]) === 1 ? 'fixed' : 'none',
      values: row.slice(1).map(String).filter((value) => JEWEL_RADIUS_LABELS[value]),
    };
  };
  const UNIQUE_ITEM_CATALOG = {
    counts: UNIQUE_ITEM_CATALOG_DATA.counts,
    items: UNIQUE_ITEM_CATALOG_DATA.items.map((row) => ({
      id: row[0],
      name: row[1],
      baseType: row[2],
      section: row[3],
      equipmentType: row[4],
      fpoe: row[5] === 1,
      alias: row[6] || '',
      rollMappingComplete: row[7] === 1,
      rollReady: row[8] === 1,
      effects: row[9].map((effectRow) => ({
        id: String(effectRow[0] || ''),
        text: effectRow[1],
        displayText: effectRow[7] || effectRow[1],
        rolls: effectRow[2].map((rollRow) => ({
          min: Number(rollRow[0]),
          max: Number(rollRow[1]),
          valueIndex: Number(rollRow[2]),
        })),
        reviewReason: effectRow[3] || '',
        description: effectRow[4] || '',
        descriptionPending: effectRow[5] === 1,
        dictionaryMissing: effectRow[6] === 1,
      })),
      equipmentTypeCode: String(row[10] || ''),
      variantLabel: String(row[11] || ''),
      signatureMagicIds: (row[12] || []).map(String),
      sourceItemId: String(row[13] || row[0]),
      jewelRadius: hydrateUniqueJewelRadius(row[14]),
    })),
  };

  const normalizeUniqueItemLookupText = (value) => String(value || '')
    .normalize('NFKC')
    .replace(/[【（(]/g, '[')
    .replace(/[】）)]/g, ']')
    .replace(/[·•‧.]/g, '')
    .replace(/\s+/g, '')
    .toLowerCase();

  const getUniqueItemLookupKey = (name, baseType) => (
    `${normalizeUniqueItemLookupText(name)}\u0001${normalizeUniqueItemLookupText(baseType)}`
  );

  const getUniqueItemGameDisplayName = (item) => {
    return String(item?.name || '').trim();
  };

  const UNIQUE_ITEMS_BY_GAME_KEY = new Map();
  const UNIQUE_ITEMS_BY_NAME = new Map();
  for (const item of UNIQUE_ITEM_CATALOG.items) {
    const names = [item.name, item.alias].filter(Boolean);
    for (const name of names) {
      const gameKey = getUniqueItemLookupKey(name, item.baseType);
      if (!UNIQUE_ITEMS_BY_GAME_KEY.has(gameKey)) UNIQUE_ITEMS_BY_GAME_KEY.set(gameKey, []);
      if (!UNIQUE_ITEMS_BY_GAME_KEY.get(gameKey).includes(item)) UNIQUE_ITEMS_BY_GAME_KEY.get(gameKey).push(item);
      const normalizedName = normalizeUniqueItemLookupText(name);
      if (!UNIQUE_ITEMS_BY_NAME.has(normalizedName)) UNIQUE_ITEMS_BY_NAME.set(normalizedName, []);
      if (!UNIQUE_ITEMS_BY_NAME.get(normalizedName).includes(item)) UNIQUE_ITEMS_BY_NAME.get(normalizedName).push(item);
    }
  }

  const getEquipmentUniqueMagicIds = (equipment) => new Set((
    equipment?.affixes ||
    equipment?.raw?.affixes ||
    equipment?.data?.affixes ||
    equipment?.raw?.data?.affixes ||
    []
  )
    .filter((affix) => Number(affix?.type) === 0)
    .flatMap((affix) => Object.keys(affix?.magics || {}))
    .map(String));

  const selectUniqueItemVariantByMagicIds = (candidates, magicIds) => {
    if (candidates.length <= 1) return candidates[0] || null;
    const signatureMatches = candidates.filter((item) => (
      item.signatureMagicIds.length > 0 && item.signatureMagicIds.every((magicId) => magicIds.has(magicId))
    ));
    if (signatureMatches.length <= 1) return signatureMatches[0] || null;
    const maxSignatureLength = Math.max(...signatureMatches.map((item) => item.signatureMagicIds.length));
    const mostSpecificMatches = signatureMatches.filter((item) => item.signatureMagicIds.length === maxSignatureLength);
    return mostSpecificMatches.length === 1 ? mostSpecificMatches[0] : null;
  };

  const selectUniqueItemVariant = (candidates, equipment) => {
    const magicIds = getEquipmentUniqueMagicIds(equipment);
    return selectUniqueItemVariantByMagicIds(candidates, magicIds);
  };

  const findUniqueCatalogItem = (equipment) => {
    const name = equipment?.name || equipment?.raw?.name || equipment?.data?.name || equipment?.raw?.data?.name;
    const baseType = equipment?.baseName || equipment?.baseType || equipment?.raw?.baseName || equipment?.raw?.baseType || equipment?.data?.baseName || equipment?.data?.baseType || equipment?.raw?.data?.baseName || equipment?.raw?.data?.baseType;
    const exact = selectUniqueItemVariant(UNIQUE_ITEMS_BY_GAME_KEY.get(getUniqueItemLookupKey(name, baseType)) || [], equipment);
    if (exact) return exact;
    const nameMatches = UNIQUE_ITEMS_BY_NAME.get(normalizeUniqueItemLookupText(name)) || [];
    const nameVariant = selectUniqueItemVariant(nameMatches, equipment);
    if (nameVariant) return nameVariant;
    const equipmentTypeCode = String(equipment?.equipmentType ?? equipment?.raw?.equipmentType ?? equipment?.data?.equipmentType ?? equipment?.raw?.data?.equipmentType ?? '');
    const typeMatches = nameMatches.filter((item) => item.equipmentTypeCode === equipmentTypeCode);
    return selectUniqueItemVariant(typeMatches, equipment);
  };

  const getUniqueCatalogAmbiguousCandidates = (equipment) => {
    const name = equipment?.name || equipment?.raw?.name || equipment?.data?.name || equipment?.raw?.data?.name;
    const baseType = equipment?.baseName || equipment?.baseType || equipment?.raw?.baseName || equipment?.raw?.baseType || equipment?.data?.baseName || equipment?.data?.baseType || equipment?.raw?.data?.baseName || equipment?.raw?.data?.baseType;
    const exactCandidates = UNIQUE_ITEMS_BY_GAME_KEY.get(getUniqueItemLookupKey(name, baseType)) || [];
    const nameCandidates = UNIQUE_ITEMS_BY_NAME.get(normalizeUniqueItemLookupText(name)) || [];
    const equipmentTypeCode = String(equipment?.equipmentType ?? equipment?.raw?.equipmentType ?? equipment?.data?.equipmentType ?? equipment?.raw?.data?.equipmentType ?? '');
    const typeCandidates = nameCandidates.filter((item) => item.equipmentTypeCode === equipmentTypeCode);
    const candidatePool = exactCandidates.length ? exactCandidates : (typeCandidates.length ? typeCandidates : nameCandidates);
    return candidatePool.length > 1 ? candidatePool : [];
  };

  const getUniqueCatalogRuntimeCandidateGroups = (item) => {
    const names = [item?.name, item?.alias].filter(Boolean);
    const seenKeys = new Set();
    return names
      .map((name) => getUniqueItemLookupKey(name, item?.baseType))
      .filter((key) => {
        if (seenKeys.has(key)) return false;
        seenKeys.add(key);
        return true;
      })
      .map((key) => UNIQUE_ITEMS_BY_GAME_KEY.get(key) || [])
      .filter((candidates) => candidates.length > 1);
  };

  const isUniqueCatalogItemRuntimeMatchReady = (item) => {
    const candidateGroups = getUniqueCatalogRuntimeCandidateGroups(item);
    if (!candidateGroups.length) return true;
    if (!item?.signatureMagicIds?.length) return false;
    return candidateGroups.every((candidates) => (
      selectUniqueItemVariantByMagicIds(candidates, new Set(item.signatureMagicIds)) === item
    ));
  };

